#define PI 3.14159267
#define PI_2 (PI * 0.5)

float det(in vec2 a, in vec2 b) { return a.x*b.y - a.y*b.x; }
float dot2(in vec2 a ) { return dot(a,a); }
float sqr(in float x) { return x*x; }

// https://www.shadertoy.com/view/WltSD7
float cos_acos_3( float x ) {
    x  =sqrt(0.5+0.5*x);
    return x*(x*(x*(x*-0.008972+0.039071)-0.107074)+0.576975)+0.5;
} 

// https://math.stackexchange.com/questions/1098487/atan2-faster-approximation
float fast_atan2(float y, float x)
{
    float ax = abs(x);
    float ay = abs(y);
    float a = min(ax, ay) / max(ax, ay);
    float s = a * a;
    float r = ((-0.0464964749 * s + 0.15931422) * s - 0.327622764) * s * a + a;
    r = (ay > ax) ? PI_2 - r : r;
    r = (x < 0.) ? PI  - r : r;
    r = r * sign(y);
    return r;
}

float sdRoundedBox( in vec2 p, in vec2 b, in float r )
{
    vec2 q = abs(p)-b+r;
    return min(max(q.x,q.y),0.0) + length(max(q,0.0)) - r;
}

//
// Samples distance, winding and arclength of an arc defined by two points and height.
//
// The 'h' is in range -1..1, and defines the height of the arc proportional to the segment p0-p1 length.
// The 'h' can can be also thought as tan(alpha/2), where alpha is the arcs tagent angle at p0.
// The shape can define up to a half a circle.
// If 'h' is positive, the circle center is on the left of the line, else on right.
//
// return a vec4(d, w, u, v) with:
// - d: the minimum distance from p to the circle arc
// - w: winding number at p
// - u: arc length from p0 to the nearest point on the curve at p (extends beyond the end points of the curve)
// - v: signed distance to the arc
//
// Based on GLyphy arc definition.
//
vec4 dwuvArc(const vec2 p, const vec2 p0, const vec2 p1, const float h)
{
    vec2 pp0 = p - p0;
    vec2 pp1 = p - p1;
    vec2 dir = p1 - p0;
    vec2 norm = vec2(-dir.y, dir.x);

    float d0 = length(pp0);
    float d1 = length(pp1);

    float insideDist = 0.;
    float dist = 0.;
    vec2 uv;

    if (abs(h) < 0.025) {
        // When the height of the curve is really small,
        // approximate it with a bend segment to avoid the radius to become really large.
        // The distance to the bent segment is not true, but it should allow slight bent
        // on the curve to meet the height.
        float ddir = dot(dir,dir);
        float segLen = sqrt(ddir);
        float t = dot(pp0, dir) / ddir;
        float tc = clamp(t, 0.0, 1.0);
        float sd = dot(pp0, norm * sign(h)) / segLen;
        float offset = (1. - sqr(2.*tc-1.)) * abs(h) * segLen * 0.5; // inverted parabola, leak at 0.5

        insideDist = (-sd - offset);
        dist = (t > 0. && t < 1.)
            ? abs(insideDist) // curve
            : min(d0, d1); // endpoint

        uv.x = t * segLen; // approximate curve length by segment length
        uv.y = insideDist * -sign(h);

    } else {
        // Find circle center & radius
        vec2 c = mix(p0, p1, .5) - norm * (h*h - 1.) / (4. * h);
        float r = distance(p0, c);

        // Check if the point is within the arc.
        vec2 p0c = p0 - c;
        vec2 p1c = p1 - c;
        bool inStart = dot(pp0, vec2(-p0c.y, p0c.x) * sign(h)) >= 0.;
        bool inEnd = dot(pp1, vec2(-p1c.y, p1c.x) * sign(h)) <= 0.;
        bool inWedge = inStart && inEnd;

        // If inside the arc wedge, return distance to the circle, else distance to end points.
        vec2 pc = p - c;        
        insideDist = length(pc) - r;
        dist = inWedge
            ? abs(insideDist) // curve
            : min(d0, d1); // endpoint

        // Parametrization
        float a0 = fast_atan2(p0c.y, p0c.x); // can precalc!
        float aa = fast_atan2(pc.y, pc.x);
        float da = (aa - a0) * sign(h);

        if (da < -PI*0.5) da += PI*2.;
        if (da > PI*1.5) da -= PI*2.;

        uv.x = da * r;
        uv.y = insideDist * -sign(h);
    }

    // winding
    float side = dot(norm, pp0);
    bvec3 cond = bvec3(p.y >= p0.y, p.y < p1.y, side > 0.);
    float inside = max(sign(insideDist), cond.z ? sign(h) : -sign(h));
	float winding = (all(cond) || all(not(cond))) ? -inside : inside;

    return vec4(dist, winding, uv);
}

//
// Samples distance, winding and length of a line segemnt defined by two points.
//
// return a vec4(d, w, u, v) with:
// - d: the minimum distance from p to the line segment
// - w: winding number at p
// - u: arc length from p0 to the nearest point on the curve at p (extends beyond the end points of the curve)
// - v: signed distance to the (infinite) line
//
// Based on https://www.shadertoy.com/view/3tdSDj
//
vec4 dwuvLine(in vec2 p, in vec2 p0, in vec2 p1)
{
	vec2 pp0 = p - p0;
    vec2 dir = p1 - p0;
    vec2 norm = vec2(-dir.y, dir.x);

    float ddir = dot(dir, dir);
    float tr = dot(pp0, dir)/ddir;
	float t = clamp(tr, 0.0, 1.0);

    // Distance
    float dist = length(pp0 - dir*t);

    // Winding
    bvec3 cond = bvec3(p.y >= p0.y, p.y < p1.y, dir.x*pp0.y > dir.y*pp0.x );
    float winding = (all(cond) || all(not(cond))) ? -1. : 1.;

    // Parametrization
    vec2 uv;
    float segLen = sqrt(ddir);
    uv.x = tr * segLen;
    uv.y = dot(pp0, norm) / segLen;

    return vec4(dist, winding, uv);
}

//
// Calc the length of a quadratic bezier at the start/end points and at the specified value for the parameter t.
//
// return vec2(l, ltot):
// - l: length of the bezier up to "t" 
// - ltot: total length of the curve
//
// Based on https://www.shadertoy.com/view/NltBRB
//
vec2 arcLenBezier(float t, vec2 p0, vec2 p1, vec2 p2)
{
    vec2 a1 = 2.0 * (p0 - 2.0 * p1 + p2);
    vec2 b1 = 2.0 * (p1 - p0);
    float k1 = dot(a1, a1);
    float k2 = 2.0 * dot(a1, b1);
    float k3 = dot(b1, b1);
    float k4 = 0.5f * k2 / k1;
    float k5 = k3 / k1 - k4 * k4;
    vec3 ti = vec3(0.0, t, 1.0); // calc at all three integration bounds at once
    vec3 vt = sqrt((ti + k4) * (ti + k4) + k5);
    vec3 sdft = sqrt(k1) * 0.5 * ((k4 + ti) * vt + k5 * log(abs(k4 + ti + vt)));
    return sdft.yz - sdft.x;
}

// Calculate winding using bary centric coordinates.
float windingBezier(in vec2 pos, in vec2 p0, in vec2 p1, in vec2 p2)
{
    // Calculate bary centric coordinates of the triangle.
    vec2 v0 = p1 - p0;
    vec2 v1 = p2 - p0;
    vec2 v2 = pos - p0;
    float den = det(v0, v1);
    float u = det(v2, v1) / den;
    float v = det(v0, v2) / den;
    float side = sign(den);

    // Use the barycentric distance from edge p2-p0 to check on which side of the edge we area, the sign will flip depending how the triange winding/facing.
    bvec3 cond = bvec3(pos.y >= p0.y, pos.y < p2.y, u*side < 0. );

    // Eval if pos is inside the bezier curve inside the triangle.
    // Using cond.z here to avoid potential gaps between the inside test and the line.
    float w = u * 0.5 + v;
    float inside = max(cond.z ? side : -side, sign((w * w) - v));

    return (all(cond) || all(not(cond))) ? -inside : inside;
}

//
// Samples distance, winding and length of a quad bezier curve defined by three points.
//
// return a vec4(d, w, u, v) with:
// - d: the minimum distance from p to the curve
// - w: winding number at p
// - u: arc length from p0 to the nearest point on the curve at p (extends beyond the end points of the curve)
// - v: signed distance to the curve
//
// Based on https://www.shadertoy.com/view/MlKcDD
//
vec4 dwuvBezier(in vec2 pos, in vec2 p0, in vec2 p1, in vec2 p2)
{
    vec2 a = p1 - p0;
    vec2 b = p0 - 2.*p1 + p2;
    vec2 c = 2.*a;
    vec2 d = p0 - pos;

    float kk = 1. / dot(b,b);
    float kx = kk * dot(a,b);
    float ky = kk * (2.*dot2(a) + dot(d,b)) / 3.;
    float kz = kk * dot(d,a);

    float p  = ky - kx*kx;
    float q  = kx * (2.*kx*kx - 3.*ky) + kz;
    float p3 = p * p * p;
    float q2 = q * q;
    float h  = q2 + 4.*p3;

    vec2 res = vec2(0.); // dist^2, t 

    if(h >= 0.) 
    {   // 1 root
        h = sqrt(h);
        vec2 x = (vec2(h, -h) - q) / 2.;
        vec2 uv = sign(x) * pow(abs(x), vec2(1. / 3.));
        float t = clamp( uv.x + uv.y - kx, 0., 1. );
        vec2  q = d + (c + b*t) * t;
        res = vec2(dot2(q), t);
    } else {
        // 3 roots
        float z = sqrt(-p);
        float m = cos_acos_3( q/(p*z*2.0) );
        float n = sqrt(1.0-m*m) * sqrt(3.0);
        vec2 t = clamp(vec2(m + m, -n - m) * z - kx, 0., 1. );
        vec2 qx = d + (c + b * t.x) * t.x;
        vec2 resx = vec2(dot2(qx), t.x);
        vec2 qy = d + (c + b * t.y) * t.y;
        vec2 resy = vec2(dot2(qy), t.y);
        res = resx.x < resy.x ? resx : resy;
    }

    float winding = windingBezier(pos, p0, p1, p2);

    // Calc parametrization (extend linearly past end points, as the curve may fold on itself).
    vec2 uv;
    float t = res.y;
    vec2 arclen = arcLenBezier(t, p0, p1, p2);
    vec2 cpos = d + (c + b * t) * t;
    vec2 cdir = normalize(c + 2.0*b * t);
    uv.x = arclen.x - dot(cpos, cdir);
    uv.y = det(cpos, cdir);

    return vec4(sqrt(res.x), winding, uv);
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // normalized pixel coordinates
    vec2 p = (2.0*fragCoord-iResolution.xy)/iResolution.y;
    vec2 m = (2.0*iMouse.xy-iResolution.xy)/iResolution.y;

    float aa = 0.01;
    float thickness = 0.075;

    // animation
    float time = iTime;
	vec2 v0 = 0.8*cos( 0.43 *iTime + vec2(0.0,2.00) + 0.0 );
	vec2 v1 = 0.8*cos( 0.51 *iTime + vec2(0.0,1.50) + 1.0 );
	vec2 v2 = 0.8*cos( 0.64 *iTime + vec2(0.0,1.0) + 1.0 );
    vec2 cp = v2;

    // sampling
    float h = cos(0.63*iTime);
    float sw = fract(0.03*iTime);
    vec4 dwuv = vec4(0.);
    if( sw < 0.4 ) {
        dwuv = dwuvArc(p, v0, v2, h);
        vec2 dir = v2 - v0;
        cp = mix(v0, v2, 0.5) - vec2(-dir.y,dir.x) * 0.5 * h;
    } else if (sw < 0.8) {
        dwuv = dwuvBezier(p, v0, v1, v2);
        cp = v1;
    } else {
        dwuv = dwuvLine(p, v0, v2);
    }


    // Dash pattern
    float offset = thickness * 0.5; // start pattern from at the tip of the round end cap.
    float filled = 0.2;
    float gap = 0.1;
    float dash = filled + gap;
    vec2 uv = dwuv.zw; // coordinate system along the curve.
    // Repeat dash shape along curve.
    // The dash shape is centered on the repeat pattern, so that the distance is symmetric, offset by gap*0.5 to align the first fast at start.
    uv.x = fract((uv.x + gap*0.5 + offset) / dash) * dash;
    float d = sdRoundedBox(uv - vec2(dash*0.5, 0.), vec2(filled/2., thickness*0.5), thickness*0.3);

    // Intersect with the curve geometry
    d = max(d, dwuv.x - thickness*0.5);

    // Color distance field.
    vec3 col = (d>0.0) ? vec3(0.9,0.6,0.3) : vec3(0.65,0.85,1.0);
	col *= 1.0 - exp(-4.0*abs(d));
	col *= 0.8 + 0.2*cos(110.0*d);

    // Winding
    if (dwuv.y < 0.)
        col = mix( col, vec3(0.0,0.5,1.), 0.25 );

    // Color across the parameter space
    vec3 vcol = mix(vec3(0., 0.6,1.), vec3(1., 1., 0), clamp((uv.y/thickness + 0.5), 0., 1.));
    col = mix( col, vcol, smoothstep(aa,-aa,d) );

    // Outline distance zero crossing
	col = mix( col, vec3(1.0), 1.0-smoothstep(0.0,aa,abs(d)) );

    // End points
    d = max(-(length(p-v0)-0.02), length(p-v0)-0.03);
    d = min( d, length(p-v2)-0.02 );
    d = min( d, length(p-cp)-0.01 );
    col = mix( col, vec3(1.,0.3,0.3), 1.0-smoothstep(0.0,aa,d) );


	fragColor = vec4(col, 1.0);
}
